extern "C" void run(const void* input1, const void* input2, void* output, int n, int parameter, int threads) {
    if (n <= 0)
        return;

    float* a = (float*)input1;
    float* result = (float*)output;
    const int requested_threads = threads > 0 ? threads : 1;
    const int team_size = std::min(requested_threads, n);

    if (n < 128 || team_size == 1) {
        binomial_put_serial(a, a + n, a + 2 * n, a + 3 * n, a + 4 * n, result, n);
        return;
    }

    // Assign each worker one contiguous range, using the actual team size so
    // runtime limits or dynamic team reduction cannot leave elements unwritten.
    #pragma omp parallel num_threads(team_size)
    {
        const int worker_count = omp_get_num_threads();
        const int worker_id = omp_get_thread_num();
        const int begin = static_cast<int>((static_cast<std::int64_t>(n) * worker_id) / worker_count);
        const int end = static_cast<int>((static_cast<std::int64_t>(n) * (worker_id + 1)) / worker_count);

        for (int i = begin; i < end; ++i) {
            float V[BINOMIAL_NUM];
            float S = a[i], X = a[n + i];
            float T = a[2 * n + i], r = a[3 * n + i];
            float v = a[4 * n + i];

            float dt = T / BINOMIAL_NUM;
            float u = expf(v * sqrtf(dt));
            float d = 1.f / u;
            float disc = expf(r * dt);
            float Pu = (disc - d) / (u - d);

            for (int j = 0; j < BINOMIAL_NUM; ++j) {
                float upow = powf(u, (float)(2 * j - BINOMIAL_NUM));
                V[j] = std::max(0.f, X - S * upow);
            }

            for (int j = BINOMIAL_NUM - 1; j >= 0; --j)
                for (int k = 0; k < j; ++k)
                    V[k] = ((1 - Pu) * V[k] + Pu * V[k + 1]) / disc;

            result[i] = V[0];
        }
    }
}

