void binomial_put_serial(float Sa[], float Xa[], float Ta[], float ra[], float va[], float result[], int count) {
    float V[BINOMIAL_NUM];
    double q_powers[BINOMIAL_NUM];

    for (int i = 0; i < count; ++i) {
        float S = Sa[i], X = Xa[i];
        float T = Ta[i], r = ra[i];
        float v = va[i];

        float dt = T / BINOMIAL_NUM;
        float u = expf(v * sqrtf(dt));
        float d = 1.f / u;
        float disc = expf(r * dt);
        float Pu = (disc - d) / (u - d);

        // Terminal indices are j=0..63, with exponents 2*j-64.
        // Generate those powers from u^-64 in steps of u^2.
        float upow = powf(u, -64.0f);
        const float upow_step = u * u;
        for (int j = 0; j < BINOMIAL_NUM; ++j) {
            V[j] = std::max(0.f, X - S * upow);
            if (j + 1 < BINOMIAL_NUM)
                upow *= upow_step;
        }

        // There are 63 effective backward updates, so the terminal weights
        // are C(63,j) * Pu^j * (1-Pu)^(63-j), with 63 discount divisions.
        double q = (double)(1.f - Pu);
